const GC=2,GR=2,S=1.1;
const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.7071068,0,0,0.7071068],down:[0.7071068,0,0,0.7071068],left:[0,0,0.7071068,0.7071068],right:[0,0,-0.7071068,0.7071068]};
const dist=s=>Math.abs(GC-s.c)+Math.abs(GR-s.r);
const won=s=>s.c===GC&&s.r===GR;
export function initialState(){return {c:0,r:0,moves:0,hint:null,msg:''};}
function hintDir(s){return s.c<GC?'right':(s.c>GC?'left':(s.r<GR?'up':'down'));}
export function reduce({state,event}){
 if(event.type!=='action')return state;
 const a=event.action,s=state;
 if(won(s))return {...s,msg:'Already at the goal. Press Reset to play again.'};
 if(a==='hint')return {...s,hint:hintDir(s),msg:'The green arrow shows a move one step closer.'};
 const d=D[a];if(!d)return s;
 const c=s.c+d[0],r=s.r+d[1];
 if(c<0||c>2||r<0||r>2)return {...s,hint:null,msg:'That move would leave the board.'};
 return {c,r,moves:s.moves+1,hint:null,msg:''};
}
export function evaluate({state}){
 const s=state||initialState();
 const x=(s.c-1)*S,z=(1-s.r)*S,w=won(s);
 const y=w?0.48:0.4;
 const nodes={token:{position:[x,y,z]},hintA:{visible:false}};
 if(s.hint&&!w){const d=D[s.hint];nodes.hintA={visible:true,position:[x+d[0]*0.32,y,z-d[1]*0.32],quaternion:Q[s.hint]};}
 const k=dist(s);
 let goal;
 if(w)goal={status:'won',message:'You reached the goal in '+s.moves+' moves. The shortest route is 4 moves'+(s.moves===4?' - perfect!':'.')};
 else goal={status:'playing',message:s.msg||('Reach the orange goal. '+k+' steps to go.')};
 return {nodes,readouts:{moves:s.moves,steps:k},goal};
}
